def hidden_rule_fn(state):
    rows = len(state)
    cols = len(state[0])
    next_state = [[0]*cols for _ in range(rows)]

    for r in range(rows):
        for c in range(cols):
            cur = state[r][c]

            # Compute von-quad neighbors (N, S, E, W) with toroidal wrap
            n = state[(r-1) % rows][c]
            s = state[(r+1) % rows][c]
            e = state[r][(c+1) % cols]
            w = state[r][(c-1) % cols]

            neighbors = [n, s, e, w]
            distinct = set(neighbors)
            D = len(distinct)

            if D == 1:
                v = neighbors[0]
                if cur == 1:
                    next_state[r][c] = v
                else:
                    next_state[r][c] = cur
            elif D == 2:
                if cur == 0:
                    next_state[r][c] = 0
                else:
                    # Count occurrences
                    counts = {}
                    for nb in neighbors:
                        counts[nb] = counts.get(nb, 0) + 1

                    max_count = max(counts.values())

                    if max_count == 2:
                        # No majority (2-2 split)
                        if 1 in distinct:
                            next_state[r][c] = 1
                        else:
                            # distinct must be {0, 2}
                            if cur in distinct:
                                next_state[r][c] = cur
                            else:
                                next_state[r][c] = 0
                    else:
                        # Clear majority (3-1 split)
                        majority = max(counts, key=counts.get)
                        if majority == cur:
                            next_state[r][c] = cur
                        else:
                            if majority == 1:
                                next_state[r][c] = 1
                            elif majority == 0:
                                next_state[r][c] = cur if cur == 2 else 0
                            else:  # majority == 2
                                next_state[r][c] = 0
            elif D == 3:
                next_state[r][c] = (2 - cur) % 3
            else:
                next_state[r][c] = cur

    return next_state
